-- Mini Canvas / Supabase PostgreSQL bootstrap. Run once in the Supabase SQL editor.
-- This is PostgreSQL SQL, but it intentionally requires Supabase-provided auth and
-- storage schemas, auth.uid(), and the anon/authenticated/service_role roles.
create extension if not exists pgcrypto;
create extension if not exists citext;
create schema if not exists app_private;
revoke all on schema app_private from public, anon, authenticated;

create type public.app_role as enum ('user','admin');
create type public.member_role as enum ('owner','editor','commenter');
create type public.asset_kind as enum ('image','video','audio');
create type public.generation_status as enum ('queued','running','succeeded','failed','refunded');
create type public.credit_entry_kind as enum ('admin_grant','reservation','settlement','refund');

create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null,display_name text not null default '新用户',avatar_path text,role public.app_role not null default 'user',disabled_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),name text not null default 'Untitled',thumbnail_path text,background text not null default '#f2f2f0',version bigint not null default 0,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.project_members(project_id uuid references public.projects(id) on delete cascade,user_id uuid references public.profiles(id) on delete cascade,role public.member_role not null,created_at timestamptz not null default now(),primary key(project_id,user_id));
create table public.project_invites(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,email citext not null,role public.member_role not null check(role<>'owner'),token_hash text not null unique,expires_at timestamptz not null,accepted_at timestamptz,invited_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table public.canvas_objects(id uuid primary key,project_id uuid not null references public.projects(id) on delete cascade,parent_id uuid references public.canvas_objects(id) on delete set null,kind text not null check(kind in('rect','ellipse','polygon','path','text','frame','group','image','video','audio','scene','image-gen','video-gen','audio-gen')),name text not null,props jsonb not null default '{}',z_index integer not null default 0,version bigint not null default 1,created_by uuid not null references public.profiles(id),updated_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.canvas_edges(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,source_id uuid not null references public.canvas_objects(id) on delete cascade,target_id uuid not null references public.canvas_objects(id) on delete cascade,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),constraint no_self_edge check(source_id<>target_id),unique(project_id,source_id,target_id));
create table public.project_operations(id bigint generated always as identity primary key,operation_id uuid not null unique,project_id uuid not null references public.projects(id) on delete cascade,project_version bigint not null,actor_id uuid not null references public.profiles(id),command jsonb not null,inverse_command jsonb,created_at timestamptz not null default now(),unique(project_id,project_version));
create table public.canvas_snapshots(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,project_version bigint not null,payload jsonb not null,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(project_id,project_version));
create table public.comments(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,object_id text,x double precision,y double precision,body text not null,color text,author_id uuid not null references public.profiles(id),resolved_at timestamptz,resolved_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.comments add column if not exists color text;
create table public.comment_replies(id uuid primary key default gen_random_uuid(),comment_id uuid not null references public.comments(id) on delete cascade,body text not null,author_id uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table public.assets(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,owner_id uuid not null references public.profiles(id),kind public.asset_kind not null,storage_path text not null unique,mime_type text not null,byte_size bigint not null check(byte_size>=0),width integer,height integer,duration_seconds numeric,source text not null check(source in('upload','generation')),created_at timestamptz not null default now());
create table public.voice_profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,project_id uuid references public.projects(id) on delete set null,project_name text not null,name text not null check(char_length(name) between 1 and 80),voice_id text not null check(char_length(voice_id) between 1 and 160),source_model text not null,last_used_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,voice_id));
create table public.project_viewports(user_id uuid not null references public.profiles(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,x double precision not null default 0,y double precision not null default 0,zoom double precision not null default 1,updated_at timestamptz not null default now(),primary key(user_id,project_id));
create table public.provider_configs(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,base_url text not null,adapter text not null check(adapter in('seedance-nz','volcengine','openai-compatible')),enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table app_private.provider_credentials(provider_id uuid primary key references public.provider_configs(id) on delete cascade,ciphertext bytea not null,updated_by uuid not null references public.profiles(id),updated_at timestamptz not null default now());
create table public.model_configs(id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.provider_configs(id) on delete cascade,model_id text not null,display_name text not null,kind text not null check(kind in('image','video','audio','chat')),capabilities jsonb not null default '{}',pricing jsonb not null default '{}',enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider_id,model_id));
create table public.credit_accounts(user_id uuid primary key references public.profiles(id) on delete cascade,balance bigint not null default 0 check(balance>=0),updated_at timestamptz not null default now());
create table public.generation_tasks(id uuid primary key default gen_random_uuid(),idempotency_key uuid not null,project_id uuid not null references public.projects(id) on delete cascade,node_id uuid not null references public.canvas_objects(id) on delete cascade,user_id uuid not null references public.profiles(id),model_config_id uuid not null references public.model_configs(id),kind public.asset_kind not null,status public.generation_status not null default 'queued',provider_task_id text,prompt text not null,input_snapshot jsonb not null default '{}',price_snapshot jsonb not null,credits_reserved bigint not null check(credits_reserved>=0),error_code text,error_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,idempotency_key));
create table public.generation_results(id uuid primary key default gen_random_uuid(),task_id uuid not null references public.generation_tasks(id) on delete cascade,asset_id uuid not null references public.assets(id),version integer not null,created_at timestamptz not null default now(),unique(task_id,version));
create table public.credit_ledger(id bigint generated always as identity primary key,user_id uuid not null references public.profiles(id),task_id uuid references public.generation_tasks(id),kind public.credit_entry_kind not null,amount bigint not null,balance_after bigint not null,actor_id uuid references public.profiles(id),note text,idempotency_key text not null unique,created_at timestamptz not null default now());
create table public.chat_sessions(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,user_id uuid not null references public.profiles(id),title text not null default '新对话',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.chat_messages(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.chat_sessions(id) on delete cascade,role text not null check(role in('user','assistant','tool')),content jsonb not null,created_at timestamptz not null default now());
create table public.agent_runs(id uuid primary key default gen_random_uuid(),session_id uuid not null references public.chat_sessions(id) on delete cascade,status text not null,selected_snapshot jsonb not null default '[]',tool_log jsonb not null default '[]',error text,started_at timestamptz not null default now(),finished_at timestamptz);
create table public.admin_audit_log(id bigint generated always as identity primary key,actor_id uuid not null references public.profiles(id),action text not null,target_type text not null,target_id text,details jsonb not null default '{}',created_at timestamptz not null default now());

create index projects_owner_idx on public.projects(owner_id) where deleted_at is null;create index members_user_idx on public.project_members(user_id);create index invites_project_idx on public.project_invites(project_id);create index invites_email_idx on public.project_invites(email) where accepted_at is null;create index objects_project_z_idx on public.canvas_objects(project_id,z_index);create index objects_parent_idx on public.canvas_objects(parent_id) where parent_id is not null;create index edges_target_idx on public.canvas_edges(target_id);create index operations_project_version_idx on public.project_operations(project_id,project_version);create index snapshots_project_idx on public.canvas_snapshots(project_id,project_version desc);create index comments_project_idx on public.comments(project_id) where resolved_at is null;create index replies_comment_idx on public.comment_replies(comment_id,created_at);create index assets_project_idx on public.assets(project_id,created_at desc);create index voice_profiles_user_project_idx on public.voice_profiles(user_id,project_name,name);create index tasks_status_idx on public.generation_tasks(status,created_at) where status in('queued','running');create index tasks_project_idx on public.generation_tasks(project_id,created_at desc);create index tasks_user_idx on public.generation_tasks(user_id,created_at desc);create index tasks_node_idx on public.generation_tasks(node_id);create index ledger_user_idx on public.credit_ledger(user_id,created_at desc);create index chats_project_user_idx on public.chat_sessions(project_id,user_id,updated_at desc);create index messages_session_idx on public.chat_messages(session_id,created_at);create index runs_session_idx on public.agent_runs(session_id,started_at desc);create index audit_actor_idx on public.admin_audit_log(actor_id,created_at desc);

create or replace function app_private.is_admin(uid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=uid and role='admin' and disabled_at is null)$$;
create or replace function app_private.project_role(pid uuid,uid uuid) returns public.member_role language sql stable security definer set search_path='' as $$select role from public.project_members where project_id=pid and user_id=uid$$;
revoke all on function app_private.is_admin(uuid),app_private.project_role(uuid,uuid) from public;grant usage on schema app_private to authenticated,service_role;grant execute on function app_private.is_admin(uuid),app_private.project_role(uuid,uuid) to authenticated,service_role;

create or replace function app_private.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$declare first_admin boolean;begin perform pg_advisory_xact_lock(hashtext('mini-canvas-first-admin'));select not exists(select 1 from public.profiles where role='admin') into first_admin;insert into public.profiles(id,email,display_name,role) values(new.id,coalesce(new.email,''),coalesce(new.raw_user_meta_data->>'display_name',split_part(coalesce(new.email,'新用户'),'@',1)),case when first_admin then 'admin'::public.app_role else 'user'::public.app_role end);insert into public.credit_accounts(user_id) values(new.id);return new;end$$;
revoke all on function app_private.handle_new_user() from public,anon,authenticated;create trigger on_auth_user_created after insert on auth.users for each row execute function app_private.handle_new_user();
create or replace function public.add_owner_membership() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.project_members(project_id,user_id,role) values(new.id,new.owner_id,'owner');return new;end$$;
revoke all on function public.add_owner_membership() from public,anon,authenticated;create trigger project_owner_membership after insert on public.projects for each row execute function public.add_owner_membership();
create or replace function app_private.prevent_project_owner_change() returns trigger language plpgsql security invoker set search_path='' as $$begin if new.owner_id is distinct from old.owner_id then raise exception 'project_owner_immutable';end if;return new;end$$;
revoke all on function app_private.prevent_project_owner_change() from public,anon,authenticated;create trigger project_owner_immutable before update on public.projects for each row execute function app_private.prevent_project_owner_change();
create or replace function public.sync_voice_project_name() returns trigger language plpgsql security definer set search_path='' as $$begin if new.name is distinct from old.name then update public.voice_profiles set project_name=new.name where project_id=new.id;end if;return new;end$$;
create trigger voice_project_name_sync after update on public.projects for each row execute function public.sync_voice_project_name();

create or replace function app_private.reserve_credits(p_task_id uuid,p_amount bigint,p_idempotency text) returns bigint language plpgsql security definer set search_path='' as $$declare uid uuid:=(select auth.uid());new_balance bigint;begin if uid is null or p_amount<0 then raise exception 'invalid request';end if;update public.credit_accounts set balance=balance-p_amount,updated_at=now() where user_id=uid and balance>=p_amount returning balance into new_balance;if new_balance is null then raise exception 'insufficient credits';end if;insert into public.credit_ledger(user_id,task_id,kind,amount,balance_after,idempotency_key) values(uid,p_task_id,'reservation',-p_amount,new_balance,p_idempotency);return new_balance;end$$;
revoke all on function app_private.reserve_credits(uuid,bigint,text) from public;grant execute on function app_private.reserve_credits(uuid,bigint,text) to authenticated,service_role;
create or replace function public.reserve_credits(p_task_id uuid,p_amount bigint,p_idempotency text) returns bigint language sql security invoker set search_path='' as $$select app_private.reserve_credits(p_task_id,p_amount,p_idempotency)$$;
revoke all on function public.reserve_credits(uuid,bigint,text) from public;grant execute on function public.reserve_credits(uuid,bigint,text) to authenticated;
create or replace function public.apply_canvas_operation(p_project uuid,p_expected bigint,p_operation uuid,p_command jsonb) returns bigint language plpgsql security invoker set search_path='' as $$declare next_version bigint;action text:=p_command->>'action';obj jsonb:=p_command->'object';begin if app_private.project_role(p_project,(select auth.uid())) not in('owner','editor') then raise exception 'forbidden';end if;update public.projects set version=version+1,updated_at=now() where id=p_project and version=p_expected returning version into next_version;if next_version is null then raise exception 'version_conflict';end if;if action='create' then insert into public.canvas_objects(id,project_id,parent_id,kind,name,props,z_index,created_by,updated_by) values((obj->>'id')::uuid,p_project,nullif(obj->>'parent_id','')::uuid,obj->>'kind',coalesce(obj->>'name','Untitled'),coalesce(obj->'props','{}'),coalesce((obj->>'z_index')::integer,0),(select auth.uid()),(select auth.uid()));elsif action='update' then update public.canvas_objects set name=coalesce(obj->>'name',name),parent_id=case when obj ? 'parent_id' then nullif(obj->>'parent_id','')::uuid else parent_id end,props=props||coalesce(obj->'props','{}'),z_index=coalesce((obj->>'z_index')::integer,z_index),version=version+1,updated_by=(select auth.uid()),updated_at=now() where id=(obj->>'id')::uuid and project_id=p_project and version=coalesce((obj->>'version')::bigint,version);if not found then raise exception 'object_version_conflict';end if;elsif action='delete' then delete from public.canvas_objects where id=(obj->>'id')::uuid and project_id=p_project;elsif action='connect' then insert into public.canvas_edges(project_id,source_id,target_id,created_by) values(p_project,(p_command->>'source_id')::uuid,(p_command->>'target_id')::uuid,(select auth.uid()));elsif action='disconnect' then delete from public.canvas_edges where id=(p_command->>'edge_id')::uuid and project_id=p_project;else raise exception 'unsupported_action';end if;insert into public.project_operations(operation_id,project_id,project_version,actor_id,command) values(p_operation,p_project,next_version,(select auth.uid()),p_command);return next_version;end$$;
revoke all on function public.apply_canvas_operation(uuid,bigint,uuid,jsonb) from public;grant execute on function public.apply_canvas_operation(uuid,bigint,uuid,jsonb) to authenticated;
create or replace function app_private.reject_edge_cycle() returns trigger language plpgsql security invoker set search_path='' as $$begin if exists(with recursive reachable(id) as(select new.target_id union select e.target_id from public.canvas_edges e join reachable r on e.source_id=r.id where e.project_id=new.project_id) select 1 from reachable where id=new.source_id) then raise exception 'edge_cycle';end if;return new;end$$;
create trigger reject_canvas_edge_cycle before insert or update on public.canvas_edges for each row execute function app_private.reject_edge_cycle();
create or replace function app_private.adjust_credits(p_user uuid,p_amount bigint,p_note text,p_key text) returns bigint language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());new_balance bigint;begin if not app_private.is_admin(actor) then raise exception 'forbidden';end if;insert into public.credit_accounts(user_id,balance) values(p_user,greatest(0,p_amount)) on conflict(user_id) do update set balance=public.credit_accounts.balance+p_amount,updated_at=now() returning balance into new_balance;if new_balance<0 then raise exception 'negative balance';end if;insert into public.credit_ledger(user_id,kind,amount,balance_after,actor_id,note,idempotency_key) values(p_user,'admin_grant',p_amount,new_balance,actor,p_note,p_key);return new_balance;end$$;
revoke all on function app_private.adjust_credits(uuid,bigint,text,text) from public;grant execute on function app_private.adjust_credits(uuid,bigint,text,text) to authenticated;
create or replace function public.admin_adjust_credits(p_user uuid,p_amount bigint,p_note text,p_key text) returns bigint language sql security invoker set search_path='' as $$select app_private.adjust_credits(p_user,p_amount,p_note,p_key)$$;
revoke all on function public.admin_adjust_credits(uuid,bigint,text,text) from public;grant execute on function public.admin_adjust_credits(uuid,bigint,text,text) to authenticated;
create or replace function app_private.protect_profile_fields() returns trigger language plpgsql security invoker set search_path='' as $$begin if (new.role<>old.role or new.disabled_at is distinct from old.disabled_at or new.email<>old.email) and not app_private.is_admin((select auth.uid())) then raise exception 'protected profile fields';end if;return new;end$$;
create trigger protect_profile_fields before update on public.profiles for each row execute function app_private.protect_profile_fields();
create or replace function app_private.settle_generation(p_task uuid,p_success boolean,p_error text default null) returns void language plpgsql security definer set search_path='' as $$declare task public.generation_tasks;new_balance bigint;begin select * into task from public.generation_tasks where id=p_task for update;if not found or task.status not in('queued','running') then return;end if;if p_success then update public.generation_tasks set status='succeeded',updated_at=now() where id=p_task;insert into public.credit_ledger(user_id,task_id,kind,amount,balance_after,idempotency_key) select task.user_id,task.id,'settlement',0,balance,'settle:'||task.id from public.credit_accounts where user_id=task.user_id on conflict(idempotency_key) do nothing;else update public.credit_accounts set balance=balance+task.credits_reserved,updated_at=now() where user_id=task.user_id returning balance into new_balance;update public.generation_tasks set status='refunded',error_message=p_error,updated_at=now() where id=p_task;insert into public.credit_ledger(user_id,task_id,kind,amount,balance_after,note,idempotency_key) values(task.user_id,task.id,'refund',task.credits_reserved,new_balance,p_error,'refund:'||task.id) on conflict(idempotency_key) do nothing;end if;end$$;
revoke all on function app_private.settle_generation(uuid,boolean,text) from public,anon,authenticated;grant execute on function app_private.settle_generation(uuid,boolean,text) to service_role;

alter table public.profiles enable row level security;alter table public.projects enable row level security;alter table public.project_members enable row level security;alter table public.project_invites enable row level security;alter table public.canvas_objects enable row level security;alter table public.canvas_edges enable row level security;alter table public.project_operations enable row level security;alter table public.canvas_snapshots enable row level security;alter table public.comments enable row level security;alter table public.comment_replies enable row level security;alter table public.assets enable row level security;alter table public.voice_profiles enable row level security;alter table public.project_viewports enable row level security;alter table public.provider_configs enable row level security;alter table public.model_configs enable row level security;alter table public.credit_accounts enable row level security;alter table public.generation_tasks enable row level security;alter table public.generation_results enable row level security;alter table public.credit_ledger enable row level security;alter table public.chat_sessions enable row level security;alter table public.chat_messages enable row level security;alter table public.agent_runs enable row level security;alter table public.admin_audit_log enable row level security;

create policy profiles_read on public.profiles for select to authenticated using(id=(select auth.uid()) or app_private.is_admin((select auth.uid())) or exists(select 1 from public.project_members mine join public.project_members peer using(project_id) where mine.user_id=(select auth.uid()) and peer.user_id=profiles.id));create policy profiles_self_update on public.profiles for update to authenticated using(id=(select auth.uid()) and disabled_at is null) with check(id=(select auth.uid()));
create policy projects_read on public.projects for select to authenticated using(owner_id=(select auth.uid()) or app_private.project_role(id,(select auth.uid())) is not null);create policy projects_create on public.projects for insert to authenticated with check(owner_id=(select auth.uid()) and not exists(select 1 from public.profiles where id=(select auth.uid()) and disabled_at is not null));create policy projects_update on public.projects for update to authenticated using(app_private.project_role(id,(select auth.uid())) in('owner','editor')) with check(app_private.project_role(id,(select auth.uid())) in('owner','editor'));
create policy members_read on public.project_members for select to authenticated using(app_private.project_role(project_id,(select auth.uid())) is not null);create policy members_owner_write on public.project_members for all to authenticated using(app_private.project_role(project_id,(select auth.uid()))='owner') with check(app_private.project_role(project_id,(select auth.uid()))='owner');
create policy invites_owner on public.project_invites for all to authenticated using(app_private.project_role(project_id,(select auth.uid()))='owner') with check(app_private.project_role(project_id,(select auth.uid()))='owner');
create policy objects_read on public.canvas_objects for select to authenticated using(app_private.project_role(project_id,(select auth.uid())) is not null);create policy objects_write on public.canvas_objects for all to authenticated using(app_private.project_role(project_id,(select auth.uid())) in('owner','editor')) with check(app_private.project_role(project_id,(select auth.uid())) in('owner','editor'));
create policy edges_read on public.canvas_edges for select to authenticated using(app_private.project_role(project_id,(select auth.uid())) is not null);create policy edges_write on public.canvas_edges for all to authenticated using(app_private.project_role(project_id,(select auth.uid())) in('owner','editor')) with check(app_private.project_role(project_id,(select auth.uid())) in('owner','editor'));
create policy operations_read on public.project_operations for select to authenticated using(app_private.project_role(project_id,(select auth.uid())) is not null);create policy operations_write on public.project_operations for insert to authenticated with check(actor_id=(select auth.uid()) and app_private.project_role(project_id,(select auth.uid())) in('owner','editor'));
create policy snapshots_read on public.canvas_snapshots for select to authenticated using(app_private.project_role(project_id,(select auth.uid())) is not null);create policy snapshots_write on public.canvas_snapshots for insert to authenticated with check(created_by=(select auth.uid()) and app_private.project_role(project_id,(select auth.uid())) in('owner','editor'));
create policy comments_read on public.comments for select to authenticated using(app_private.project_role(project_id,(select auth.uid())) is not null);create policy comments_create on public.comments for insert to authenticated with check(author_id=(select auth.uid()) and app_private.project_role(project_id,(select auth.uid())) is not null);create policy comments_update on public.comments for update to authenticated using(author_id=(select auth.uid()) or app_private.project_role(project_id,(select auth.uid())) in('owner','editor')) with check(app_private.project_role(project_id,(select auth.uid())) is not null);
create policy replies_member on public.comment_replies for select to authenticated using(exists(select 1 from public.comments c where c.id=comment_id and app_private.project_role(c.project_id,(select auth.uid())) is not null));create policy replies_create on public.comment_replies for insert to authenticated with check(author_id=(select auth.uid()) and exists(select 1 from public.comments c where c.id=comment_id and app_private.project_role(c.project_id,(select auth.uid())) is not null));
create policy assets_read on public.assets for select to authenticated using(app_private.project_role(project_id,(select auth.uid())) is not null);create policy assets_write on public.assets for all to authenticated using(owner_id=(select auth.uid()) and app_private.project_role(project_id,(select auth.uid())) in('owner','editor')) with check(owner_id=(select auth.uid()) and app_private.project_role(project_id,(select auth.uid())) in('owner','editor'));
create policy voice_profiles_self on public.voice_profiles for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy project_viewports_self on public.project_viewports for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy providers_read on public.provider_configs for select to authenticated using(true);create policy providers_admin on public.provider_configs for all to authenticated using(app_private.is_admin((select auth.uid()))) with check(app_private.is_admin((select auth.uid())));create policy models_read on public.model_configs for select to authenticated using(enabled or app_private.is_admin((select auth.uid())));create policy models_admin on public.model_configs for all to authenticated using(app_private.is_admin((select auth.uid()))) with check(app_private.is_admin((select auth.uid())));
create policy accounts_self on public.credit_accounts for select to authenticated using(user_id=(select auth.uid()) or app_private.is_admin((select auth.uid())));create policy ledger_self on public.credit_ledger for select to authenticated using(user_id=(select auth.uid()) or app_private.is_admin((select auth.uid())));
create policy tasks_read on public.generation_tasks for select to authenticated using(user_id=(select auth.uid()) or app_private.project_role(project_id,(select auth.uid())) is not null);create policy tasks_create on public.generation_tasks for insert to authenticated with check(user_id=(select auth.uid()) and app_private.project_role(project_id,(select auth.uid())) in('owner','editor'));create policy results_read on public.generation_results for select to authenticated using(exists(select 1 from public.generation_tasks t where t.id=task_id and app_private.project_role(t.project_id,(select auth.uid())) is not null));
create policy sessions_self on public.chat_sessions for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and app_private.project_role(project_id,(select auth.uid())) is not null);create policy messages_self on public.chat_messages for all to authenticated using(exists(select 1 from public.chat_sessions s where s.id=session_id and s.user_id=(select auth.uid()))) with check(exists(select 1 from public.chat_sessions s where s.id=session_id and s.user_id=(select auth.uid())));create policy runs_self on public.agent_runs for select to authenticated using(exists(select 1 from public.chat_sessions s where s.id=session_id and s.user_id=(select auth.uid())));create policy audit_admin on public.admin_audit_log for select to authenticated using(app_private.is_admin((select auth.uid())));

-- self-host 镜像自带的 storage 初始表较旧，storage-api 启动前先把列补齐（云端已有则 no-op）
-- install_roles=false：storage-api 的 0002 migration 会 CREATE ROLE，与镜像 init-scripts 冲突
alter database postgres set storage.install_roles to 'false';
alter role supabase_storage_admin set storage.install_roles to 'false';
alter table storage.buckets add column if not exists public boolean not null default false;
alter table storage.buckets add column if not exists file_size_limit bigint;
alter table storage.buckets add column if not exists allowed_mime_types text[];
alter table storage.buckets add column if not exists avif_autodetection boolean not null default false;
alter table storage.objects add column if not exists owner_id text;
alter table storage.objects add column if not exists version text;
-- 不要预建 user_metadata：storage-api 的 0025 migration 用 ADD COLUMN（无 IF NOT EXISTS）会失败

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('project-assets','project-assets',false,524288000,array['image/jpeg','image/png','image/webp','image/svg+xml','video/mp4','video/webm','audio/mpeg','audio/mp4','audio/aac','audio/x-aac','audio/ogg','application/ogg','audio/webm','audio/wav','audio/x-wav','audio/vnd.wav','audio/flac','audio/x-m4a']) on conflict(id) do update set allowed_mime_types=excluded.allowed_mime_types;
-- 用 split_part 而不是 storage.foldername：storage-api 自带 migration 会 drop foldername，
-- 若 policy 依赖它会导致 storage 启动迁移失败。
create policy asset_files_read on storage.objects for select to authenticated using(bucket_id='project-assets' and app_private.project_role((split_part(name,'/',1))::uuid,(select auth.uid())) is not null);create policy asset_files_insert on storage.objects for insert to authenticated with check(bucket_id='project-assets' and app_private.project_role((split_part(name,'/',1))::uuid,(select auth.uid())) in('owner','editor') and owner_id=(select auth.uid()::text));create policy asset_files_update on storage.objects for update to authenticated using(bucket_id='project-assets' and owner_id=(select auth.uid()::text)) with check(bucket_id='project-assets' and owner_id=(select auth.uid()::text));create policy asset_files_delete on storage.objects for delete to authenticated using(bucket_id='project-assets' and owner_id=(select auth.uid()::text));

